WITH paused_queues AS MATERIALIZED ( SELECT COALESCE(array_agg(queue_name), ARRAY[]::text[]) AS names FROM harvest_queue_pauses WHERE queue_name = ANY($2) ), paused_activities AS MATERIALIZED ( SELECT COALESCE(array_agg(activity_name), ARRAY[]::text[]) AS names FROM harvest_activity_pauses ), expired_runs AS MATERIALIZED ( SELECT id FROM harvest_workflow_executions WHERE state = 'RUNNING' AND deadline_at < NOW() UNION ALL SELECT id FROM harvest_workflow_executions WHERE state = 'RUNNING' AND chain_deadline_at < NOW() ), seek_heads AS MATERIALIZED ( SELECT h.seek_id, h.seek_ctid, h.seek_rank, h.seek_priority, h.seek_due, h.seek_pinned, h.seek_concurrency_key, h.seek_concurrency_cap, h.seek_task_type, h.seek_plain, h.head_queue, h.head_kind, h.head_new_start, row_number() OVER ( PARTITION BY h.head_queue, h.head_kind, h.head_new_start ORDER BY h.seek_priority DESC, h.seek_due ASC ) AS seek_rn FROM ( SELECT s.*, FALSE AS seek_pinned, q.name AS head_queue, k.head_kind, k.new_start_head AS head_new_start FROM (SELECT DISTINCT name FROM unnest($2::text[]) AS u(name)) AS q CROSS JOIN paused_queues CROSS JOIN paused_activities CROSS JOIN (VALUES ('workflow', FALSE), ('workflow', TRUE), ('activity', FALSE), ('activity', TRUE)) AS k(head_kind, new_start_head) CROSS JOIN LATERAL ( SELECT id AS seek_id, ctid AS seek_ctid, CASE WHEN sticky_worker_id = $1 AND sticky_until > NOW() THEN 1 ELSE 0 END AS seek_rank, priority AS seek_priority, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) AS seek_due, concurrency_key AS seek_concurrency_key, concurrency_cap AS seek_concurrency_cap, task_type AS seek_task_type, (concurrency_key IS NULL AND required_build_id IS NULL AND required_capabilities IS NULL AND rate_limit_key IS NULL) AS seek_plain FROM harvest_task_queue WHERE queue_name = q.name AND task_type = k.head_kind AND state = 'PENDING' AND (new_start AND attempt = 0) >= k.new_start_head AND (new_start AND attempt = 0) <= k.new_start_head AND scheduled_at <= NOW() AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = $1 OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = $1 ) AND CASE WHEN task_type = 'activity' AND activity_name = ANY(paused_activities.names) THEN FALSE WHEN task_type = 'activity' AND required_capabilities IS NULL AND activity_name = ANY($6) THEN FALSE WHEN task_type = 'activity' AND activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest($6::text[]) AS marked WHERE left(marked, 1) = chr(1) )) THEN FALSE ELSE TRUE END ORDER BY (new_start AND attempt = 0), priority DESC, scheduled_at ASC LIMIT 32 ) s WHERE NOT (q.name = ANY(paused_queues.names)) UNION ALL SELECT p.*, TRUE, NULL, NULL, NULL FROM paused_queues CROSS JOIN paused_activities CROSS JOIN LATERAL ( SELECT * FROM ( SELECT id AS seek_id, ctid AS seek_ctid, CASE WHEN sticky_worker_id = $1 AND sticky_until > NOW() THEN 1 ELSE 0 END AS seek_rank, priority AS seek_priority, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) AS seek_due, concurrency_key AS seek_concurrency_key, concurrency_cap AS seek_concurrency_cap, task_type AS seek_task_type, (concurrency_key IS NULL AND required_build_id IS NULL AND required_capabilities IS NULL AND rate_limit_key IS NULL) AS seek_plain FROM harvest_task_queue WHERE sticky_worker_id >= $1 AND sticky_worker_id <= $1 AND harvest_task_queue.state = 'PENDING' AND queue_name = ANY($2) AND sticky_until > NOW() AND scheduled_at <= NOW() AND NOT (queue_name = ANY(paused_queues.names)) AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = $1 OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = $1 ) AND CASE WHEN task_type = 'activity' AND activity_name = ANY(paused_activities.names) THEN FALSE WHEN task_type = 'activity' AND required_capabilities IS NULL AND activity_name = ANY($6) THEN FALSE WHEN task_type = 'activity' AND activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest($6::text[]) AS marked WHERE left(marked, 1) = chr(1) )) THEN FALSE ELSE TRUE END ORDER BY sticky_worker_id, queue_name, priority DESC, scheduled_at OFFSET 0 ) pins ORDER BY seek_priority DESC, seek_due ASC LIMIT 32 ) p ) h WHERE $4::BIGINT IS NULL OR $4::BIGINT <= 0 ), seek_bounds AS MATERIALIZED ( SELECT seek_pinned AS bound_pinned, seek_priority AS bound_priority, seek_due AS bound_due, head_queue AS bound_queue, head_kind AS bound_kind, head_new_start AS bound_new_start FROM seek_heads WHERE seek_rn = 32 ), seek_candidate AS ( SELECT id, task_type, concurrency_key, concurrency_cap, rate_limit_key, activity_name, workflow_exec_id FROM harvest_task_queue CROSS JOIN paused_queues CROSS JOIN paused_activities WHERE harvest_task_queue.state = (SELECT 'PENDING'::text) AND scheduled_at <= NOW() AND NOT (harvest_task_queue.queue_name = ANY(paused_queues.names)) AND harvest_task_queue.ctid = ANY(ARRAY( SELECT w.seek_ctid FROM seek_heads w WHERE NOT EXISTS (SELECT 1 FROM seek_bounds b WHERE (b.bound_pinned OR w.seek_rank = 0) AND ( (b.bound_pinned AND w.seek_rank = 0) OR w.seek_priority < b.bound_priority OR (w.seek_priority = b.bound_priority AND w.seek_due > b.bound_due) ) ) )) AND ( schedule_to_close_at IS NULL OR schedule_to_close_at > NOW() ) AND ( sticky_worker_id IS NULL OR sticky_worker_id = $1 OR sticky_until IS NULL OR sticky_until <= NOW() ) AND ( session_id IS NULL OR sticky_worker_id = $1 ) AND ( task_type != 'activity' OR activity_name IS NULL OR required_capabilities IS NOT NULL OR NOT (activity_name = ANY($6)) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(ARRAY( SELECT substr(marked, 2) FROM unnest($6::text[]) AS marked WHERE left(marked, 1) = chr(1) ))) ) AND ( task_type != 'activity' OR activity_name IS NULL OR NOT (activity_name = ANY(paused_activities.names)) ) AND concurrency_key IS NULL AND required_build_id IS NULL AND ( task_type <> 'workflow' OR workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM harvest_workflow_executions e WHERE e.id = harvest_task_queue.workflow_exec_id AND e.state = 'PAUSED' ) ) AND ( workflow_exec_id IS NULL OR NOT EXISTS ( SELECT 1 FROM expired_runs x WHERE x.id = harvest_task_queue.workflow_exec_id ) ) AND required_capabilities IS NULL AND rate_limit_key IS NULL AND NOT EXISTS (SELECT 1 FROM seek_heads np WHERE NOT np.seek_plain) ORDER BY CASE WHEN sticky_worker_id = $1 AND sticky_until > NOW() THEN 1 ELSE 0 END DESC, CASE WHEN $4::BIGINT IS NOT NULL AND $4::BIGINT > 0 THEN priority + FLOOR(EXTRACT(EPOCH FROM (NOW() - scheduled_at)) / $4::BIGINT)::INT ELSE priority END DESC, (scheduled_at + CASE WHEN new_start AND attempt = 0 THEN INTERVAL '30 seconds' ELSE INTERVAL '0 seconds' END) ASC LIMIT 1 FOR UPDATE SKIP LOCKED ), candidate AS ( SELECT * FROM seek_candidate ), fresh_now AS MATERIALIZED ( SELECT clock_timestamp() AS ts FROM (SELECT 1 AS one) base LEFT JOIN ( SELECT 1 AS x FROM candidate c ) locked ON TRUE ), run_expired_now AS MATERIALIZED ( SELECT EXISTS ( SELECT 1 FROM candidate c JOIN harvest_workflow_executions e ON e.id = c.workflow_exec_id WHERE e.state = 'RUNNING' AND (e.deadline_at < (SELECT ts FROM fresh_now) OR e.chain_deadline_at < (SELECT ts FROM fresh_now)) ) AS expired ), claimed AS ( UPDATE harvest_task_queue SET state = 'RUNNING', worker_id = $1, started_at = NOW(), attempt = attempt + 1, wake_requested = FALSE FROM candidate WHERE harvest_task_queue.id = candidate.id AND NOT (SELECT expired FROM run_expired_now) RETURNING harvest_task_queue.* ), claim_lean_fallback AS MATERIALIZED ( SELECT NOT EXISTS (SELECT 1 FROM seek_candidate) AND (EXISTS (SELECT 1 FROM seek_heads) OR ($4::BIGINT IS NOT NULL AND $4::BIGINT > 0)) AS claim_fallback ) SELECT claimed.id, claimed.queue_name, claimed.task_type, claimed.workflow_exec_id, claimed.activity_name, claimed.activity_id, claimed.input, claimed.state, claimed.priority, claimed.worker_id, claimed.attempt, claimed.max_attempts, claimed.scheduled_at, claimed.started_at, claimed.completed_at, claimed.last_heartbeat_at, claimed.heartbeat_details, claimed.heartbeat_timeout, claimed.start_to_close, claimed.schedule_to_start, claimed.retry_policy, claimed.output, claimed.error, claimed.sticky_worker_id, claimed.sticky_until, claimed.sticky_timeout, claimed.trace_context, claimed.concurrency_key, claimed.concurrency_cap, claimed.required_build_id, claimed.rate_limit_key, claimed.crash_strikes, claimed.schedule_to_close_at, claimed.required_capabilities, claimed.context_headers, claimed.created_at, claimed.wake_requested, claimed.session_id, claimed.capability_misses, claimed.capability_miss_workers, claimed.capability_miss_handler, claimed.timer_fires_at, claimed.handler_started_attempt, claimed.timed_out_claims, claimed.handler_started_at, claimed.new_start, claimed.fairness_key, fb.claim_fallback FROM claim_lean_fallback fb LEFT JOIN claimed ON TRUE